export const technique="## Contoh TEKNIK gaya Cara Kerja (scene 1 dari satu shot bersambung: laptop 3D berputar pelan sambil layarnya membuka di engsel lalu menyala; tiru cara menggambarnya, BUKAN isi adegannya)\n```js\nconst INK = \"#1c2433\", BLUE = \"#3b5bdb\", SKY = \"#4dabf7\", HOT = \"#ff7a45\", OK = \"#12b886\", MU = \"#6b7685\", WH = \"#f8fafc\";\nconst flat = { wobble: 0, hatch: false };\nconst num = (v, d = 1) => v.toFixed(d).replace(\".\", \",\");\nconst mix = (a, b, k) => a + (b - a) * s.ease.inOut(s.clamp(k, 0, 1));\n// ---- screen furniture (does not zoom; drawn over the object, with a soft halo to stay readable) ----\nconst halo = (fn) => {\n  ctx.save();\n  ctx.shadowColor = \"rgba(238,242,247,0.95)\";\n  ctx.shadowBlur = 22;\n  fn();\n  fn();\n  ctx.restore();\n};\n// step + a big two-line title on the left: \"02 / 04 ——\", the first line in ink, the second\n// on a blue highlighter plate so it reads over anything\nconst title = (step, total, a, b) => {\n  const k = s.at(0, 0.5), k2 = s.at(0.15, 0.5);\n  const pad = (n) => String(n).padStart(2, \"0\");\n  halo(() => {\n    s.text(pad(step) + \" / \" + pad(total), 72, 66, { size: 16, color: INK, align: \"left\", alpha: k });\n    s.line(150, 64, 150 + 50 * k, 64, { stroke: INK, width: 2, ...flat });\n    s.text3d(a, 70, 104 + (1 - k) * 14, { size: 38, depth: 0, color: INK, align: \"left\", alpha: k });\n  });\n  if (!b || k2 <= 0) return;\n  ctx.save();\n  ctx.font = '800 34px \"Plus Jakarta Sans\", \"Segoe UI\", system-ui, sans-serif';\n  const w = ctx.measureText(b).width;\n  ctx.restore();\n  s.rect(62, 126, (w + 22) * s.ease.out(k2), 46, { r: 10, fill: BLUE, stroke: WH, width: 3, ...flat });\n  s.text3d(b, 73, 149, { size: 34, depth: 0, color: WH, align: \"left\", alpha: k2 });\n};\n// a round gauge on the right: the arc fills with the reading, the number in the middle, the\n// unit under it, and the state in a small white capsule with a coloured dot\nconst gauge = (value, unit, frac, label, col) => {\n  const cx = 596, cy = 104, r = 72, a0 = Math.PI * 0.75, span = Math.PI * 1.5;\n  const k = s.at(0.1, 0.5);\n  if (k <= 0) return;\n  s.group({ x: cx, y: cy, scale: (0.85 + 0.15 * k) * 0.62, alpha: k }, () => {\n    s.circle(0, 0, r + 14, { fill: \"rgba(255,255,255,0.94)\", stroke: \"none\", ...flat });\n    s.arc(0, 0, r, a0, a0 + span, { stroke: \"#dbe2eb\", width: 12, ...flat });\n    const f = s.clamp(frac, 0, 1);\n    if (f > 0.005) s.arc(0, 0, r, a0, a0 + span * f, { stroke: col, width: 12, ...flat });\n    s.text3d(value, 0, 2, { size: 42, depth: 0, color: INK });\n    s.text(unit, 0, 38, { size: 16, color: MU });\n    const w = label.length * 12 + 44;\n    s.rect(-w / 2, r + 22, w, 36, { r: 18, fill: WH, stroke: \"#dbe2eb\", width: 2, ...flat });\n    s.circle(-w / 2 + 18, r + 40, 6, { fill: col, stroke: \"none\", ...flat });\n    s.text(label, 10, r + 41, { size: 18, color: INK });\n  });\n};\n// ---- a tiny 3D engine: x right, y back, z up; yaw turns the view, pitch looks down ----\nconst PITCH = 0.62;\nconst view = (p, yaw) => {\n  const c = Math.cos(yaw), si = Math.sin(yaw);\n  return [p[0] * c - p[1] * si, p[0] * si + p[1] * c, p[2]];\n};\nconst P = (p, yaw) => {\n  const [X, Y, Z] = view(p, yaw);\n  return [X, -Z * Math.cos(PITCH) - Y * Math.sin(PITCH)];\n};\nconst hex = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));\nconst mixHex = (a, b, k) => \"#\" + hex(a).map((v, i) => Math.round(v + (hex(b)[i] - v) * s.clamp(k, 0, 1)).toString(16).padStart(2, \"0\")).join(\"\");\nconst shade = (h, f) => \"rgb(\" + hex(h).map((v) => Math.round(Math.min(255, f > 1 ? v + (255 - v) * (f - 1) : v * f))).join(\",\") + \")\";\nconst LIGHT = [-0.35, -0.55, 0.76];\nconst sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];\nconst cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];\nconst dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];\n// a solid box from (x0,y0,z0) to (x1,y1,z1); T moves its corners (e.g. the lid's hinge); only\n// the faces turned to the camera are drawn, each lit by how it faces the light\nconst box = (a, b, col, yaw, o = {}) => {\n  const T = o.T ?? ((p) => p);\n  const c = [];\n  for (let i = 0; i < 8; i++) c.push(T([i & 1 ? b[0] : a[0], i & 2 ? b[1] : a[1], i & 4 ? b[2] : a[2]]));\n  const mid = c.reduce((m, p) => [m[0] + p[0] / 8, m[1] + p[1] / 8, m[2] + p[2] / 8], [0, 0, 0]);\n  const toCam = [0, -Math.cos(PITCH), Math.sin(PITCH)];\n  for (const f of [[0, 1, 3, 2], [4, 5, 7, 6], [0, 1, 5, 4], [2, 3, 7, 6], [0, 2, 6, 4], [1, 3, 7, 5]]) {\n    let n = cross(sub(c[f[1]], c[f[0]]), sub(c[f[3]], c[f[0]]));\n    const fc = f.reduce((m, i) => [m[0] + c[i][0] / 4, m[1] + c[i][1] / 4, m[2] + c[i][2] / 4], [0, 0, 0]);\n    if (dot(n, sub(fc, mid)) < 0) n = n.map((v) => -v);\n    const len = Math.hypot(...n) || 1;\n    n = n.map((v) => v / len);\n    if (dot(view(n, yaw), toCam) <= 0.001) continue;\n    const lit = 0.68 + 0.42 * Math.max(0, dot(n, LIGHT));\n    s.shape(f.map((i) => P(c[i], yaw)), { fill: shade(col, lit), stroke: INK, width: o.line ?? 1.8, alpha: o.alpha ?? 1, ...flat });\n  }\n};\n// a flat quad or polygon lying in 3D (screens, keys, labels), drawn as is\nconst quad = (pts, fill, yaw, o = {}) => s.shape(pts.map((p) => P(p, yaw)), { fill, stroke: o.stroke ?? \"none\", width: o.width ?? 1.5, alpha: o.alpha ?? 1, ...flat });\nconst ring = (cx, cy, z, r, n = 28) => Array.from({ length: n }, (_, i) => [cx + Math.cos((i / n) * Math.PI * 2) * r, cy + Math.sin((i / n) * Math.PI * 2) * r, z]);\n// ---- the laptop: base x -170..170, y -115..115, z 0..18; the lid hinges on the back edge ----\n// st: lid 0..1 (closed..open), on 0..1 (screen), open 0..1 (keyboard deck lifted off), heat 0..1, fan (angle)\nconst world = (st, yaw) => {\n  const o = st.open ?? 0, heat = st.heat ?? 0;\n  const ang = (st.lid ?? 0) * 1.95;\n  const hinge = (p) => {\n    const dy = p[1] - 115, dz = p[2] - 18;\n    return [p[0], 115 + dy * Math.cos(ang) + dz * Math.sin(ang), 18 - dy * Math.sin(ang) + dz * Math.cos(ang)];\n  };\n  // the lid with its screen: drawn first once it leans back behind the base, last while it's over it\n  const lid = () => {\n    box([-170, -115, 18], [170, 115, 27], \"#c3ccd8\", yaw, { T: hinge });\n    if (ang < 0.9) return;\n    const scr = [[-156, -101, 17.6], [156, -101, 17.6], [156, 101, 17.6], [-156, 101, 17.6]].map(hinge);\n    quad(scr, \"#141a24\", yaw, { stroke: INK });\n    const on = st.on ?? 0;\n    if (on > 0) {\n      quad(scr, BLUE, yaw, { alpha: 0.85 * on });\n      for (let i = 0; i < 4; i++) {\n        const y0 = 60 - i * 34, w = [220, 160, 250, 120][i];\n        quad([[-130, y0, 17.4], [-130 + w, y0, 17.4], [-130 + w, y0 - 14, 17.4], [-130, y0 - 14, 17.4]].map(hinge), WH, yaw, { alpha: 0.75 * on });\n      }\n    }\n  };\n  if (ang > 1.57) lid();\n  // base: a tray (bottom + walls) holding the parts\n  box([-170, -115, 0], [170, 115, 5], \"#aeb8c6\", yaw);\n  box([-170, 105, 5], [170, 115, 14], \"#b7c1ce\", yaw);\n  box([-170, -115, 5], [-160, 105, 14], \"#b7c1ce\", yaw);\n  if (o > 0) {\n    box([-150, -100, 5], [150, -48, 14], \"#465066\", yaw);\n    quad([[-60, -100, 14.2], [60, -100, 14.2], [60, -48, 14.2], [-60, -48, 14.2]], \"#5a6580\", yaw);\n    box([-150, -38, 5], [70, 98, 8], \"#22577a\", yaw);\n    box([-140, 70, 8], [-70, 90, 12], \"#2f9e44\", yaw);\n    box([-62, 10, 8], [-8, 64, 13], mixHex(\"#9aa6b6\", HOT, heat), yaw);\n    box([-8, 30, 8], [92, 44, 11], \"#d08850\", yaw);\n    // the fan: a dark ring with blades turning\n    box([82, 12, 5], [158, 98, 7], \"#2a3140\", yaw);\n    quad(ring(120, 55, 13, 38), \"#2a3140\", yaw, { stroke: INK });\n    const fa = st.fan ?? 0;\n    for (let i = 0; i < 7; i++) {\n      const a0 = fa + (i / 7) * Math.PI * 2;\n      const bl = [[8, -0.18], [34, -0.32], [34, 0.12], [8, 0.2]].map(([r, d]) => [120 + Math.cos(a0 + d) * r, 55 + Math.sin(a0 + d) * r, 13.4]);\n      quad(bl, \"#9fb0c8\", yaw, { stroke: INK, width: 1.2 });\n    }\n    quad(ring(120, 55, 13.6, 9, 14), \"#e3e8ef\", yaw, { stroke: INK, width: 1.2 });\n  }\n  box([160, -115, 5], [170, 105, 14], \"#b7c1ce\", yaw);\n  box([-170, -115, 5], [170, -105, 14], \"#c9d1dc\", yaw);\n  // the keyboard deck: lifts straight up and fades as the inside is shown\n  const lift = 260 * s.ease.inOut(o);\n  if (o < 1) {\n    const up = (p) => [p[0], p[1], p[2] + lift];\n    box([-170, -115, 12], [170, 115, 18], \"#d5dce6\", yaw, { T: up, alpha: 1 - o });\n    for (let r = 0; r < 4; r++) for (let k = 0; k < 12; k++) {\n      const x0 = -150 + k * 25, y0 = 70 - r * 24;\n      quad([[x0, y0, 18.3], [x0 + 20, y0, 18.3], [x0 + 20, y0 - 19, 18.3], [x0, y0 - 19, 18.3]].map(up), \"#2a3140\", yaw, { alpha: 1 - o });\n    }\n    quad([[-50, -100, 18.3], [50, -100, 18.3], [50, -40, 18.3], [-50, -40, 18.3]].map(up), \"#c3ccd8\", yaw, { stroke: INK, width: 1.2, alpha: 1 - o });\n  }\n  if (ang <= 1.57) lid();\n};\n// draw the world through a camera { x, y, z, yaw }: projected point (x, y) at screen (360, 600)\nconst shoot = (cam, st) => {\n  s.group({ x: 360 - cam.x * cam.z, y: 600 - cam.y * cam.z, scale: cam.z }, () => world(st, cam.yaw));\n};\nconst toScreen = (cam, p) => {\n  const [x, y] = P(p, cam.yaw);\n  return [360 + (x - cam.x) * cam.z, 600 + (y - cam.y) * cam.z];\n};\n// aim the camera at a 3D point\nconst aim = (p, z, yaw) => {\n  const [x, y] = P(p, yaw);\n  return { x, y, z, yaw };\n};\n// camera from a to b over [t0, t1]; it ends exactly on b, where the next scene's camera starts\nconst move = (a, b, t0 = 0, t1 = s.dur) => {\n  const k = (s.t - t0) / (t1 - t0);\n  return { x: mix(a.x, b.x, k), y: mix(a.y, b.y, k), z: mix(a.z, b.z, k), yaw: mix(a.yaw, b.yaw, k) };\n};\nconst CAM_WHOLE = aim([0, 10, 75], 1.35, -0.55);\nconst CAM_BASE = aim([0, 0, 10], 1.45, -0.55);\nconst CAM_CPU = aim([-35, 37, 10], 2.3, -0.55);\nconst CAM_FAN = aim([95, 45, 10], 2.1, -0.4);\n// kamera: aim([0, 10, 30], 1.3, -1.0) -> CAM_WHOLE (laptop utuh berputar pelan, layar terbuka)\nconst lid = s.clamp((s.t - 0.5) / 1.1, 0, 1);\nconst on = s.ease.out(s.clamp((s.t - 1.7) / 0.4, 0, 1));\nconst deg = 112 * s.ease.inOut(lid);\nconst cam = move(aim([0, 10, 30], 1.3, -1.0), CAM_WHOLE);\nshoot(cam, { lid: s.ease.inOut(lid), on });\nconst [tx, ty] = toScreen(cam, [0, 115, 160]);\ns.text3d(\"KLIK!\", tx + 120, ty - 20, { size: 40, color: HOT, side: INK, depth: 6, rotate: 0.1, draw: s.pop(1.7, 0.4), alpha: 1 - s.at(2.5, 0.4) });\n// screen layer last, over the object\ntitle(1, 4, \"Buka,\", \"menyala.\");\ngauge(Math.round(deg) + \"°\", \"sudut layar\", deg / 112, on > 0.3 ? \"MENYALA\" : \"MATI\", on > 0.3 ? OK : MU);\ns.sfx(\"click\", 0.5, 0.6);\ns.sfx(\"ding\", 1.7, 0.5);\n```\n\n";
